import { readApiResponse, type ApiResult } from "../web/src/lib/api-response";

function handleResult(result: ApiResult): void {
  switch (result.kind) {
    case "success":
      // data는 unknown이므로 필드에 접근하려면 별도 타입 검증이 필요하다.
      console.log("성공:", result.status, result.data);
      break;
    case "api-error":
      console.log("API 오류:", result.status, result.code, result.message);
      for (const violation of result.details?.violations ?? []) {
        console.log("입력 오류:", violation.field, violation.reason);
      }
      break;
    case "lookup-failed":
      // 응답을 받기 전에 실패했다면 status는 null이다.
      console.log("조회 실패:", result.status, result.code);
      break;
  }
}

export async function runExamples(): Promise<void> {
  // 아래 응답과 오류는 모두 모의 자료이며 실제 네트워크 요청은 없다.
  const success = await readApiResponse(
    new Response(JSON.stringify({ id: "example-1", title: "예시 결과" }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    }),
  );
  handleResult(success); // kind: "success"

  const apiError = await readApiResponse(
    new Response(
      JSON.stringify({
        code: "VALIDATION_ERROR",
        message: "입력값을 확인해 주세요.",
        details: {
          violations: [{ field: "title", reason: "제목을 입력해 주세요." }],
        },
      }),
      { status: 400, headers: { "Content-Type": "application/json" } },
    ),
  );
  handleResult(apiError); // kind: "api-error"

  // Promise를 먼저 await하면 readApiResponse가 거절을 처리할 수 없다.
  const lookupFailed = await readApiResponse(
    Promise.reject<Response>(new TypeError("모의 조회 실패")),
  );
  handleResult(lookupFailed); // kind: "lookup-failed", status: null
}

void runExamples();

import {
  readApiResponse,
  type ApiResult,
} from "../web/src/lib/api-response.ts";

// 모든 입력은 합성 자료이며 실제 네트워크 요청은 하지 않는다.
function handleResult(result: ApiResult): void {
  switch (result.kind) {
    case "success": {
      // 성공 데이터는 unknown이므로 사용할 필드를 먼저 확인한다.
      const data = result.data;
      if (
        typeof data === "object" &&
        data !== null &&
        "title" in data &&
        typeof data.title === "string"
      ) {
        console.log("성공:", result.status, data.title);
      } else {
        console.log("성공 데이터 형식 확인 필요:", result.status);
      }
      break;
    }
    case "api-error":
      console.log("API 오류:", result.status, result.code, result.message);
      for (const violation of result.details?.violations ?? []) {
        console.log("입력 오류:", violation.field, violation.reason);
      }
      break;
    case "lookup-failed":
      // 조회 실패는 빈 데이터로 바꾸지 않는다. 응답이 없으면 status는 null이다.
      console.log("조회 실패:", result.status, result.code);
      break;
  }
}

export async function runApiResponseExamples(): Promise<void> {
  const success = await readApiResponse(
    new Response(JSON.stringify({ title: "합성 예시 자산" }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    }),
  );
  handleResult(success);

  const apiError = await readApiResponse(
    new Response(
      JSON.stringify({
        code: "VALIDATION_ERROR",
        message: "입력값을 확인해 주세요.",
        details: {
          violations: [{ field: "title", reason: "제목은 필수입니다." }],
        },
      }),
      { status: 400, headers: { "Content-Type": "application/json" } },
    ),
  );
  handleResult(apiError);

  // 거절된 Promise를 먼저 await하지 않고 함수에 직접 넘긴다.
  const lookupFailed = await readApiResponse(
    Promise.reject<Response>(new Error("합성 조회 실패")),
  );
  handleResult(lookupFailed);
}

void runApiResponseExamples();
